static int ui_text_width(const char*s,float scale){const char*begin64=s;float width=0;for(;*s;s++){unsigned length64=0;int icon64=(s==begin64||s[-1]==' '||s[-1]=='/'||s[-1]=='(')?ui_button_token64(begin64,s,&length64):-1;if(icon64>=0){width+=fmaxf(16*scale,ui_native_size65(scale)+3);s+=length64-1;continue;}unsigned c=(unsigned char)*s;if(c<32||c>127)c='?';width+=ui_native_advance65(c,scale);}return (int)ceilf(width);}
static void ui_scaled(int x,int y,float scale,const char*fmt,...){char line[160];va_list a;va_start(a,fmt);vsnprintf(line,sizeof(line),fmt,a);va_end(a);float xx=x;for(unsigned i=0;line[i];i++){unsigned length64=0;int icon64=(!i||line[i-1]==' '||line[i-1]=='/'||line[i-1]=='(')?ui_button_token64(line,line+i,&length64):-1;if(icon64>=0){ui_button_draw64(icon64,xx,y,scale);xx+=fmaxf(16*scale,ui_native_size65(scale)+3);i+=length64-1;continue;}unsigned c=(unsigned char)line[i];if(c<32||c>127)c='?';unsigned k=c-32;if(c!=' ')hud_glyph53(xx,y,16*scale,16*scale,(k%16)*16,(k/16)*16,16,16);xx+=ui_native_advance65(c,scale);}}
/* Controller hints use uppercase command labels; selection descriptions stay prose. */
static void ui_hint_case200(char*line){for(unsigned i=0;line[i];i++)if(line[i]==':'){unsigned start=i;while(start&&line[start-1]!='|'&&!(start>1&&line[start-1]==' '&&line[start-2]==' '))start--;for(unsigned j=start;j<i;j++)if(line[j]>='a'&&line[j]<='z')line[j]-='a'-'A';}}
static void ui_hint64(int x,int y,float scale,const char*fmt,...){char line[160];va_list a;va_start(a,fmt);vsnprintf(line,sizeof(line),fmt,a);va_end(a);ui_hint_case200(line);ui_scaled(x,y,scale,"%s",line);}
/* Measure actual glyph/icon ink to center instructions inside a panel body. */
static void ui_hint_center200(int x,int y,int width,int height,float scale,const char*text){char line[160];snprintf(line,sizeof(line),"%s",text);ui_hint_case200(line);int top=16,bottom=0;unsigned size=ui_native_size65(scale);const char*begin=line;for(const char*p=line;*p;p++){unsigned n=0;int icon=(p==begin||p[-1]==' '||p[-1]=='/'||p[-1]=='(')?ui_button_token64(begin,p,&n):-1;if(icon>=0){if(2<top)top=2;if((int)size+4>bottom)bottom=size+4;p+=n-1;continue;}unsigned c=(unsigned char)*p;if(c<32||c>127)c='?';const unsigned char*b=nativeCrop180[(size-7)*192+c-32];if(b[3]){if(b[1]<top)top=b[1];if(b[1]+b[3]>bottom)bottom=b[1]+b[3];}}if(bottom<top)top=bottom=0;int xx=x+(width-ui_text_width(line,scale))/2,yy=y+(height-(bottom-top))/2-top;ui_scaled(xx,yy,scale,"%s",line);}

static void ui_light(int x,int y,float scale,const char*text){const char*begin64=text;float xx=x;for(;*text;text++){unsigned length64=0;int icon64=(text==begin64||text[-1]==' '||text[-1]=='/'||text[-1]=='(')?ui_button_token64(begin64,text,&length64):-1;if(icon64>=0){ui_button_draw64(icon64,xx,y,scale);xx+=fmaxf(16*scale,ui_native_size65(scale)+3);text+=length64-1;continue;}unsigned c=(unsigned char)*text;if(c<32||c>127)c='?';unsigned k=c-32;if(c!=' ')hud_glyph53(xx,y,16*scale,16*scale,(k%16)*16,160+(k/16)*16,16,16);xx+=ui_native_advance65(c,scale);}}
static int ui_wrap(const char*text,char lines[8][96],int maxWidth,float scale){int row=0,len=0;memset(lines,0,8*96);while(*text&&row<8){while(*text==' ')text++;if(!*text)break;const char*end=text;while(*end&&*end!=' ')end++;int word=(int)(end-text);for(int j=0;j<word;j++){char c=text[j];if(len&&ui_text_width(lines[row],scale)+ui_text_width((char[]){c,0},scale)>maxWidth){row++;len=0;if(row>=8)return 8;}if(len>=94){row++;len=0;if(row>=8)return 8;}lines[row][len++]=c;lines[row][len]=0;}text=end;if(*text&&len<94){char trial[96];memcpy(trial,lines[row],96);trial[len]=' ';trial[len+1]=0;const char*next=text;while(*next==' ')next++;int n=0;char upcoming[96];while(next[n]&&next[n]!=' '&&n<94){upcoming[n]=next[n];n++;}upcoming[n]=0;if(ui_text_width(trial,scale)+ui_text_width(upcoming,scale)>maxWidth){row++;len=0;}else {lines[row][len++]=' ';lines[row][len]=0;}}}return row<8?row+(len>0):8;}
static int ui_popup(int x,int bottom,const char*text,int maxWidth,float scale){scale=1.f;char lines[8][96];int n=ui_wrap(text,lines,maxWidth-16,scale);if(!n)return bottom;int width=32;for(int i=0;i<n;i++){int w=ui_text_width(lines[i],scale)+16;if(w>width)width=w;}if(width>maxWidth)width=maxWidth;if(x<0)x=(640-width)/2;int h=n*16+8,y=bottom-h;hud_panel(x,y,width,h);for(int i=0;i<n;i++)ui_scaled(x+8,y+3+i*16,scale,"%s",lines[i]);return y;}

/* Height may wrap within its reserved region, but its top-left is stable. */
static void ui_fixed_popup(int x,int y,const char*text,int width,int maxLines){char lines[8][96];int n=ui_wrap(text,lines,width-16,1);if(!n)return;if(maxLines<1)maxLines=1;if(maxLines>8)maxLines=8;if(n>maxLines){n=maxLines;int len=(int)strlen(lines[n-1]);while(len&&ui_text_width(lines[n-1],1)>width-40)lines[n-1][--len]=0;if(len<91)strcat(lines[n-1],"...");}int fit=32;for(int i=0;i<n;i++){int w=ui_text_width(lines[i],1)+16;if(w>fit)fit=w;}if(fit<width)width=fit;hud_panel(x,y,width,n*16+8);for(int i=0;i<n;i++)ui_scaled(x+8,y+3+i*16,1,"%s",lines[i]);}

/* Measured single-line labels. Bold is a one-pixel overstrike, without a new atlas. */
/* Fit the actual discrete native glyph size, then ellipsize at the minimum. */
static void ui_fit47(int x,int y,int width,float scale,const char*text){char line[160];snprintf(line,sizeof(line),"%s",text);while(ui_text_width(line,scale)>width&&ui_native_size65(scale)>8)scale=ui_font_smaller200(scale);if(ui_text_width(line,scale)>width){size_t n=strlen(line);while(n&&ui_text_width(line,scale)+ui_text_width("...",scale)>width)line[--n]=0;if(n+3<sizeof(line))strcat(line,"...");}ui_scaled(x,y,scale,"%s",line);}
static void ui_bold_fit47(int x,int y,int width,const char*text){ui_fit47(x,y,width,1,text);}

/* nxdk lroundf is an asserting stub. UI values are bounded before conversion. */
static int ui_round47a(float value){return value<0?(int)(value-.5f):(int)(value+.5f);}
